// Validate the posted job and turn it into the shared job shape.
const body = $('Webhook').first().json.body ?? {};
const str = v => (typeof v === 'string' ? v.trim() : '');
const job = {
  job_id: 'manual_' + $now.toMillis(),
  source: 'manual',
  title: str(body.title),
  company: str(body.company),
  location: str(body.location),
  salary: str(body.salary),
  url: str(body.url),
  description: str(body.description).slice(0, 20000),
};
const errors = ['title', 'company', 'description'].filter(f => !job[f]).map(f => `${f} is required`);
if (job.url && !/^https?:\/\//i.test(job.url)) errors.push('url must start with http:// or https://');
return [{ json: { ...job, valid: errors.length === 0, errors } }];

// Build one Claude Messages API request per job.
// Structured outputs (output_config.format) make the response match the schema.
const cfg = $('Scoring config').first().json;

const SYSTEM_PROMPT = `You are a recruitment screening assistant. You compare one job listing against one
candidate profile and return ONLY valid JSON, no prose, no code fences.

Scoring guide:
- 80–100: strong fit on core skills, level and location/remote
- 60–79: good fit with 1–2 learnable gaps
- 40–59: partial fit, several gaps
- 0–39: poor fit or wrong seniority/location

Rules:
- Judge only on the information given. Do not invent requirements.
- If salary is missing, do not penalise.
- Penalise roles requiring 5+ years in a specific tool, or people-management of large teams.
- Location: "Location check" was worked out by code. Use it as given. Never estimate distances
  or work patterns yourself. "ok" or "possible": do not reduce the score for location.
  "unknown": at most a small reduction. "probably too far": score at most 45.
  "too far": score at most 35. remote_or_local_ok is true only for "ok" or "possible".
- Prefer full-stack TypeScript/React/React Native, .NET/C#, and API/integration roles.
- Treat AI/automation work as a bonus, not a requirement.
- Penalise roles centred on Java, Python, Salesforce, embedded or industrial automation.
- matched_skills: skills that the listing asks for AND the profile lists. Nothing else.
- missing_skills: skills that the listing asks for and the profile does not list. Never add a skill
  the listing does not mention, even if it is under NOT LEARNED.
- A framework is separate from its language: C# or .NET does not cover ASP.NET or Blazor. But if the
  candidate knows the language, count a missing framework as a small learnable gap.
- matched_skills and missing_skills: up to 6 short strings each.
- reason: one sentence, max 25 words.`;

const SCHEMA = {
  type: 'object',
  properties: {
    score: { type: 'integer', description: 'Match score 0-100' },
    matched_skills: { type: 'array', items: { type: 'string' } },
    missing_skills: { type: 'array', items: { type: 'string' } },
    seniority_fit: { type: 'string', enum: ['junior', 'mid', 'senior', 'unclear'] },
    remote_or_local_ok: { type: 'boolean' },
    reason: { type: 'string' },
  },
  required: ['score', 'matched_skills', 'missing_skills', 'seniority_fit', 'remote_or_local_ok', 'reason'],
  additionalProperties: false,
};

// ===== Location helpers (same code wherever a job's location is judged) =====
const geoKey = loc => String(loc ?? '').split(/[,(]/)[0].trim();
// "GU212JX" or "GL50" -> outcode; anything else is a place name.
const outcodeOf = s => {
  const t = s.toUpperCase().replace(/\s+/g, '');
  return /^([A-Z]{1,2}\d[A-Z\d]?)(\d[A-Z]{2})$/.exec(t)?.[1] ?? (/^[A-Z]{1,2}\d[A-Z\d]?$/.test(t) ? t : null);
};
const geoUrl = key => outcodeOf(key)
  ? 'https://api.postcodes.io/outcodes/' + outcodeOf(key)
  : 'https://api.postcodes.io/places?limit=5&q=' + encodeURIComponent(key);
const geoPoint = resp => {
  const r = resp?.result;
  const p = Array.isArray(r) ? ['City', 'Town', 'Suburban Area', 'Village'].map(t => r.find(x => x.local_type === t)).find(Boolean) : r;
  return p && p.latitude != null ? { lat: Number(p.latitude), lon: Number(p.longitude) } : null;
};
// Straight-line miles.
const milesBetween = (a, b) => {
  const rad = x => x * Math.PI / 180;
  const h = Math.sin(rad(b.lat - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lon - a.lon) / 2) ** 2;
  return Math.round(2 * 3958.8 * Math.asin(Math.sqrt(h)));
};
const isCountry = key => /^(|uk|united kingdom|england|scotland|wales|great britain|remote|nationwide|home.?based)$/i.test(key);
// remote / remote offered / hybrid / on-site / unclear, from the words of the listing.
const workMode = job => {
  const head = `${job.title ?? ''} | ${job.location ?? ''}`, text = `${head} | ${job.description ?? ''}`;
  const strong = /\b(fully|100%|completely|entirely|permanently)[ -]remote\b|\bremote[ -](first|only|based)\b|\bbased remotely\b|\bremote \(?(uk|within the uk)\b|\b(location|working|work pattern)\s*[:-]?\s*(predominantly |mostly |mainly )?remote\b|\b(predominantly|mostly|mainly) remote\b/i;
  const start = String(job.description ?? '').slice(0, 200), offered = /\/ ?remote working\b|\bremote (working|work) (is )?(available|possible|offered|considered)\b/i;
  if (/\bremote\b/i.test(head) && !/\b(no|not) remote\b/i.test(head) && !/hybrid/i.test(head)) return 'remote';
  if (/\(remote\b[^)]*\)/i.test(start)) return 'remote';
  if (strong.test(text) && !/\b(no|not) (fully|100%|completely) remote\b/i.test(text)) return 'remote';
  if (/\bhybrid\b(?![ -]?(cloud|infrastructure|environment|mobile|app|azure|identity|network|model of))/i.test(text) || /\b(one|two|three|four|[1-4])(\s*(-|to|–)\s*[1-5])? days?( a| per| each)?( week)? ?(in|at|on|from)[ -](the |our )?(office|site|home)/i.test(text)) return 'hybrid';
  if (offered.test(text)) return 'remote offered';
  if (/\b(on[- ]?site|office[- ]based|in[- ]office|in[- ]person)\b/i.test(text) && !/\bremote\b/i.test(text)) return 'on-site';
  return 'unclear';
};
const locationVerdict = (mode, miles, c) => {
  const hy = c.hybrid_miles, on = c.onsite_miles;
  if (mode === 'remote') return 'ok';
  if (mode === 'remote offered') return miles != null && miles <= on ? 'ok' : 'possible';
  if (miles == null) return 'unknown';
  if (miles > hy) return mode === 'unclear' ? 'probably too far' : 'too far';
  if (mode === 'hybrid' || miles <= on) return 'ok';
  return mode === 'on-site' ? 'too far' : 'possible';
};
// The place lookup covers Great Britain only.
const NI = { lat: 54.6, lon: -5.93 };
const locate = (job, point, c) => {
  if (!point && /northern ireland|\bbelfast\b|\bcounty antrim\b/i.test(job.location ?? '')) point = NI;
  const miles = point ? milesBetween(c.home, point) : null, mode = workMode(job);
  return { work_mode: mode, miles, location_verdict: locationVerdict(mode, miles, c) };
};
// ===== End of location helpers =====
const point = geoPoint($input.first().json);
return $('Validate input').all().map(i => {
  const j = { ...i.json, ...locate(i.json, point, cfg) };
  const userMessage = [
    'CANDIDATE PROFILE:',
    cfg.candidate_profile,
    '',
    'JOB LISTING:',
    `Title: ${j.title}`,
    `Company: ${j.company || 'Not stated'}`,
    `Location: ${j.location || 'Not stated'}`,
    `Salary: ${j.salary || 'Not stated'}`,
    `Location check: ${j.location_verdict ?? 'unknown'} (work pattern: ${j.work_mode ?? 'unclear'}; ${j.miles == null ? 'distance unknown' : j.miles + ' miles from home'})`,
    'Description:',
    String(j.description || 'Not provided').slice(0, 6000),
  ].join('\n');

  return { json: {
    ...j,
    claude_request: {
      model: cfg.model,
      max_tokens: 2000,
      system: SYSTEM_PROMPT,
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
      messages: [{ role: 'user', content: userMessage }],
    },
  }};
});

// Parse and validate each Claude response. One bad response never breaks the run:
// it falls back to score = null with the reason recorded.
const jobs = $('Build Claude request').all();

const fallback = (why) => ({
  score: null, matched_skills: [], missing_skills: [],
  seniority_fit: 'unclear', remote_or_local_ok: null, reason: `parse error: ${why}`,
});

const parse = (resp) => {
  if (!resp || resp.error) {
    const e = resp?.error;
    return fallback(typeof e === 'string' ? e : (e?.message ?? 'request failed'));
  }
  if (resp.stop_reason === 'refusal') return fallback('model refused');
  if (resp.stop_reason === 'max_tokens') return fallback('response cut off');
  const text = (resp.content ?? []).find(b => b.type === 'text')?.text;
  if (!text) return fallback('no text in response');
  let data;
  try {
    data = JSON.parse(text.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, ''));
  } catch (e) {
    return fallback('invalid JSON');
  }
  if (!Number.isInteger(data.score) || data.score < 0 || data.score > 100) {
    return fallback('score not an integer 0-100');
  }
  const list = (a) => (Array.isArray(a) ? a.map(String).slice(0, 6) : []);
  return {
    score: data.score,
    matched_skills: list(data.matched_skills),
    missing_skills: list(data.missing_skills),
    seniority_fit: data.seniority_fit ?? 'unclear',
    remote_or_local_ok: typeof data.remote_or_local_ok === 'boolean' ? data.remote_or_local_ok : null,
    reason: String(data.reason ?? '').trim(),
  };
};

return $input.all().map((item, idx) => {
  const { claude_request, ...job } = jobs[idx]?.json ?? {};
  const resp = item.json;
  // Location caps are enforced here: the model may say "capped" and still score higher.
  const parsed = parse(resp), cap = { 'probably too far': 45, 'too far': 35 }[job.location_verdict];
  if (cap != null && parsed.score > cap) parsed.score = cap;
  if (job.location_verdict) parsed.remote_or_local_ok = ['ok', 'possible'].includes(job.location_verdict);
  return { json: {
    ...job,
    ...parsed,
    input_tokens: resp?.usage?.input_tokens ?? 0,
    output_tokens: resp?.usage?.output_tokens ?? 0,
  }};
});

// Map the scored job to the sheet's columns, with the CV link if one was made.
const today = $now.setZone('Europe/London').toFormat('yyyy-MM-dd');
const cvs = Object.fromEntries($('Generate CV').all().map(i => i.json).filter(r => r.job_id).map(r => [r.job_id, r]));
const briefs = Object.fromEntries($('Generate brief').all().map(i => i.json).filter(r => r.job_id).map(r => [r.job_id, r]));
return $('Parse score').all().map(i => ({ json: {
  job_id: i.json.job_id,
  date_found: today,
  source: i.json.source,
  title: i.json.title,
  company: i.json.company,
  location: i.json.location,
  salary: i.json.salary,
  url: i.json.url,
  score: i.json.score ?? '',
  matched_skills: (i.json.matched_skills ?? []).join(', '),
  missing_skills: (i.json.missing_skills ?? []).join(', '),
  reason: i.json.reason ?? '',
  status: 'New',
  cv_link: cvs[i.json.job_id]?.cv_link ?? '',
  cv_generated_at: cvs[i.json.job_id]?.cv_generated_at ?? '',
  tailoring_notes: cvs[i.json.job_id]?.tailoring_notes ?? '',
  job_brief_link: briefs[i.json.job_id]?.job_brief_link ?? '',
}}));

// Return the score to the caller (without internal fields).
const r = $('Parse score').first().json;
const row = $('Prepare sheet rows').first().json;
return [{ json: {
  job_id: r.job_id, title: r.title, company: r.company,
  score: r.score, matched_skills: r.matched_skills, missing_skills: r.missing_skills,
  seniority_fit: r.seniority_fit, remote_or_local_ok: r.remote_or_local_ok, reason: r.reason,
  logged_to_sheet: true,
  cv_link: row.cv_link || null,
  job_brief_link: row.job_brief_link || null,
  tailoring_notes: row.tailoring_notes || null,
}}];

// The job, if a CV was made for it. An empty result still continues, so the job is always logged.
const made = new Map($('Generate CV').all().map(i => i.json).filter(r => r.job_id && r.cv_ok).map(r => [r.job_id, r.cv_link]));
const today = $now.setZone('Europe/London').toFormat('yyyy-MM-dd');
return $('Parse score').all().map(i => i.json).filter(j => made.has(j.job_id)).map(j => ({ json: { ...j, date_found: today, cv_link: made.get(j.job_id) } }));

// ===== Location helpers (same code wherever a job's location is judged) =====
const geoKey = loc => String(loc ?? '').split(/[,(]/)[0].trim();
// "GU212JX" or "GL50" -> outcode; anything else is a place name.
const outcodeOf = s => {
  const t = s.toUpperCase().replace(/\s+/g, '');
  return /^([A-Z]{1,2}\d[A-Z\d]?)(\d[A-Z]{2})$/.exec(t)?.[1] ?? (/^[A-Z]{1,2}\d[A-Z\d]?$/.test(t) ? t : null);
};
const geoUrl = key => outcodeOf(key)
  ? 'https://api.postcodes.io/outcodes/' + outcodeOf(key)
  : 'https://api.postcodes.io/places?limit=5&q=' + encodeURIComponent(key);
const geoPoint = resp => {
  const r = resp?.result;
  const p = Array.isArray(r) ? ['City', 'Town', 'Suburban Area', 'Village'].map(t => r.find(x => x.local_type === t)).find(Boolean) : r;
  return p && p.latitude != null ? { lat: Number(p.latitude), lon: Number(p.longitude) } : null;
};
// Straight-line miles.
const milesBetween = (a, b) => {
  const rad = x => x * Math.PI / 180;
  const h = Math.sin(rad(b.lat - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lon - a.lon) / 2) ** 2;
  return Math.round(2 * 3958.8 * Math.asin(Math.sqrt(h)));
};
const isCountry = key => /^(|uk|united kingdom|england|scotland|wales|great britain|remote|nationwide|home.?based)$/i.test(key);
// remote / remote offered / hybrid / on-site / unclear, from the words of the listing.
const workMode = job => {
  const head = `${job.title ?? ''} | ${job.location ?? ''}`, text = `${head} | ${job.description ?? ''}`;
  const strong = /\b(fully|100%|completely|entirely|permanently)[ -]remote\b|\bremote[ -](first|only|based)\b|\bbased remotely\b|\bremote \(?(uk|within the uk)\b|\b(location|working|work pattern)\s*[:-]?\s*(predominantly |mostly |mainly )?remote\b|\b(predominantly|mostly|mainly) remote\b/i;
  const start = String(job.description ?? '').slice(0, 200), offered = /\/ ?remote working\b|\bremote (working|work) (is )?(available|possible|offered|considered)\b/i;
  if (/\bremote\b/i.test(head) && !/\b(no|not) remote\b/i.test(head) && !/hybrid/i.test(head)) return 'remote';
  if (/\(remote\b[^)]*\)/i.test(start)) return 'remote';
  if (strong.test(text) && !/\b(no|not) (fully|100%|completely) remote\b/i.test(text)) return 'remote';
  if (/\bhybrid\b(?![ -]?(cloud|infrastructure|environment|mobile|app|azure|identity|network|model of))/i.test(text) || /\b(one|two|three|four|[1-4])(\s*(-|to|–)\s*[1-5])? days?( a| per| each)?( week)? ?(in|at|on|from)[ -](the |our )?(office|site|home)/i.test(text)) return 'hybrid';
  if (offered.test(text)) return 'remote offered';
  if (/\b(on[- ]?site|office[- ]based|in[- ]office|in[- ]person)\b/i.test(text) && !/\bremote\b/i.test(text)) return 'on-site';
  return 'unclear';
};
const locationVerdict = (mode, miles, c) => {
  const hy = c.hybrid_miles, on = c.onsite_miles;
  if (mode === 'remote') return 'ok';
  if (mode === 'remote offered') return miles != null && miles <= on ? 'ok' : 'possible';
  if (miles == null) return 'unknown';
  if (miles > hy) return mode === 'unclear' ? 'probably too far' : 'too far';
  if (mode === 'hybrid' || miles <= on) return 'ok';
  return mode === 'on-site' ? 'too far' : 'possible';
};
// The place lookup covers Great Britain only.
const NI = { lat: 54.6, lon: -5.93 };
const locate = (job, point, c) => {
  if (!point && /northern ireland|\bbelfast\b|\bcounty antrim\b/i.test(job.location ?? '')) point = NI;
  const miles = point ? milesBetween(c.home, point) : null, mode = workMode(job);
  return { work_mode: mode, miles, location_verdict: locationVerdict(mode, miles, c) };
};
// ===== End of location helpers =====
const key = geoKey($('Validate input').first().json.location);
return [{ json: { url: isCountry(key) ? '' : geoUrl(key) } }];
